// Helper functions for filtering
export const getMedicinesByCategory = (category: Medicine['category']) => {
  return MEDICINES_DATA.filter(med => med.category === category);
};

export const getMedicinesByCrop = (crop: string) => {
  return MEDICINES_DATA.filter(med => 
    med.crops.some(c => c.toLowerCase().includes(crop.toLowerCase()))
  );
};

export const searchMedicines = (query: string) => {
  const q = query.toLowerCase();
  return MEDICINES_DATA.filter(med =>
    med.name.toLowerCase().includes(q) ||
    med.saltName.toLowerCase().includes(q) ||
    med.targetPests.some(p => p.toLowerCase().includes(q)) ||
    med.crops.some(c => c.toLowerCase().includes(q))
  );
};